const item = $input.first().json;
const config = item.agentConfig || {};
const projectSchema = item.projectSchema || null;
const collectionNamesStatic = item.collectionNamesStatic || [];

const body = item.body || item;

const sessionId = body.sessionId || item.sessionId || null;
const userId = body.userId || item.userId || null;
const email = body.email || item.email || null;
const role = body.role || item.role || null;
const message = body.message || body.query || body.prompt || item.message || item.query || item.prompt || null;
const timestamp = body.timestamp || item.timestamp || new Date().toISOString();

const user = { id: userId, userId, email, role, sessionId };
const requestId = `${sessionId || 'session'}_${Date.now()}`;

const errors = [];
if (!message || typeof message !== 'string') errors.push('Missing required body.message');
if (!config.mongoUri || config.mongoUri === 'PASTE_YOUR_MONGODB_URI_HERE') errors.push('MongoDB URI is not configured in Agent Config node');
if (!config.databaseName || config.databaseName === 'PASTE_YOUR_DATABASE_NAME_HERE') errors.push('MongoDB database name is not configured in Agent Config node');
if (!config.openaiApiKey || config.openaiApiKey === 'PASTE_YOUR_OPENAI_API_KEY_HERE') errors.push('OpenAI API key is not configured in Agent Config node');

return [{
  json: {
    ok: errors.length === 0,
    statusCode: errors.length ? 400 : 200,
    stage: errors.length ? 'input_or_config_validation' : 'normalized',
    errors,
    answer: errors.length ? `Configuration / input error: ${errors.join('; ')}` : null,
    requestId, sessionId, userId, email, role, message, timestamp, user,
    webhookMeta: {
      headers: item.headers || {}, params: item.params || {}, query: item.query || {},
      webhookUrl: item.webhookUrl || null, executionMode: item.executionMode || null
    },
    config,
    projectSchema,
    collectionNamesStatic
  }
}];

const { MongoClient } = require('mongodb');
const client = new MongoClient($json.config.mongoUri, { serverSelectionTimeoutMS: 8000, connectTimeoutMS: 8000, socketTimeoutMS: 12000, maxPoolSize: 2 });
try {
  await client.connect();
  const db = client.db($json.config.databaseName);
  const limit = Number($json.config.memoryLimit || 8);
  const memory = await db.collection($json.config.memoryCollection || '_agent_chat_memory')
    .find({ sessionId: $json.sessionId })
    .sort({ createdAt: -1 })
    .limit(limit)
    .toArray();
  memory.reverse();
  const compact = memory.map(m => ({
    userMessage: m.userMessage,
    assistantAnswerSummary: typeof m.assistantAnswer === 'string' ? m.assistantAnswer.slice(0, 600) : '',
    intent: m.intent ? {
      intentType: m.intent.intentType,
      questionStyle: m.intent.questionStyle || null,
      targetEntity: m.intent.targetEntity,
      scopeHint: m.intent.scopeHint,
      userGoal: m.intent.userGoal,
      subjectEntity: m.intent.subjectEntity || null
    } : null,
    plan: m.plan || null,
    providedFields: m.providedFields || null,
    success: m.success !== false,
    failureReason: m.failureReason || null,
    operation: m.operation,
    collection: m.collection,
    resultCount: m.resultCount,
    lastEntities: Array.isArray(m.lastEntities) ? m.lastEntities : [],
    exportType: m.exportType || null,
    createdAt: m.createdAt
  }));
  return [{ json: { ...$json, memory: compact } }];
} catch (e) {
  return [{ json: { ...$json, memory: [], memoryWarning: e.message } }];
} finally {
  await client.close();
}

const previous = $('Build Intent Understanding Prompt').first().json;
let intent = {};
try { intent = JSON.parse($json.choices?.[0]?.message?.content || '{}'); } catch (e) {}
intent.intentType = intent.intentType || 'read';
intent.questionStyle = intent.questionStyle || 'open';
intent.userGoal = intent.userGoal || previous.message;
intent.needsDatabase = intent.needsDatabase !== false;
intent.expectedFormat = intent.expectedFormat || 'plain';
intent.isFeasible = intent.isFeasible !== false;
intent.relatedEntities = Array.isArray(intent.relatedEntities) ? intent.relatedEntities : [];
intent.exportFormat = intent.exportFormat || null;
intent.scopeHint = intent.scopeHint || 'unknown';
intent.requiresClarification = !!intent.requiresClarification;
intent.subjectEntity = intent.subjectEntity || null;
intent.resolvedFrom = intent.resolvedFrom || null;
return [{ json: { ...previous, intent } }];

const { MongoClient } = require('mongodb');
const staticNames = $json.collectionNamesStatic || [];
if ($json.intent && $json.intent.needsDatabase === false) {
  return [{ json: { ...$json, collectionNames: staticNames, liveCollectionNames: [], collectionListSource: 'static-only-no-db-needed' } }];
}
const client = new MongoClient($json.config.mongoUri, { serverSelectionTimeoutMS: 8000, connectTimeoutMS: 8000, socketTimeoutMS: 12000, maxPoolSize: 2 });
try {
  await client.connect();
  const db = client.db($json.config.databaseName);
  const collections = await db.listCollections({}, { nameOnly: true }).toArray();
  const liveCollectionNames = collections.map(c => c.name).filter(n => !String(n).startsWith('_agent_')).sort();
  const merged = Array.from(new Set([...staticNames, ...liveCollectionNames])).sort();
  return [{ json: { ...$json, collectionNames: merged, liveCollectionNames, collectionListSource: 'merged-static-and-live' } }];
} catch (e) {
  return [{ json: { ...$json, collectionNames: staticNames, liveCollectionNames: [], collectionListSource: 'static-fallback-db-error', collectionListWarning: e.message } }];
} finally { await client.close(); }

const projectSchema = $json.projectSchema || {};
const collectionsDirectory = Object.entries(projectSchema.collections || {}).map(([key, def]) => ({
  key, model: def.model, aliases: def.aliases || []
}));

const systemPrompt = "Choose the MongoDB collections needed for the user request (school-management agent).

Return STRICT JSON only:
{ "selectedCollections": ["..."], "reason": "short reason" }

Rules:
- Use ONLY names from availableCollections.
- Prefer names listed in projectSchemaCollections.
- Include relation collections needed for $lookup:
  * parent -> children needs students + users
  * student names of class X needs students + users
  * attendance report by name needs attendances + students + users
  * fees of class 10 by name needs fees + students + users
  * exam results: exams + exammarks + students + users + subjects (or marksheets + students + users + subjects)
  * transport bills: transportpayments + transportroutes + users + students
  * salary slips: salaryslips + salarystaffs + teachers + users
- For any person-by-name query always include users.
- Max " + ($json.config.maxCollectionsToSample || 6) + " collections.
- Casual/invalid/non-DB returns [].";

return [{ json: { ...$json, openaiCollectionSelectionRequestBody: { model: $json.config.openaiModel, temperature: 0.1, response_format: { type: 'json_object' }, messages: [
  { role: 'system', content: systemPrompt },
  { role: 'user', content: JSON.stringify({ message: $json.message, user: $json.user, intent: $json.intent, recentMemory: $json.memory || [], availableCollections: $json.collectionNames, projectSchemaCollections: collectionsDirectory }, null, 2) }
] } } }];

const previous = $('Build Collection Selection Prompt').first().json;
let parsed = {};
try { parsed = JSON.parse($json.choices?.[0]?.message?.content || '{}'); } catch (e) {}
const available = new Set(previous.collectionNames || []);
let selectedCollections = Array.isArray(parsed.selectedCollections) ? parsed.selectedCollections.filter(n => available.has(n)) : [];
if (previous.intent?.needsDatabase === false) selectedCollections = [];
if (!selectedCollections.length && previous.intent?.needsDatabase !== false) {
  const msg = `${previous.message || ''} ${previous.intent?.targetEntity || ''} ${previous.intent?.userGoal || ''}`.toLowerCase();
  selectedCollections = (previous.collectionNames || []).filter(name => {
    const n = String(name).toLowerCase();
    return msg.includes(n) || msg.includes(n.replace(/s$/, '')) ||
      (msg.includes('child') && (n.includes('student') || n.includes('user') || n.includes('parent'))) ||
      (msg.includes('kid') && (n.includes('student') || n.includes('user') || n.includes('parent'))) ||
      (msg.includes('student') && n.includes('student')) ||
      (msg.includes('user') && n.includes('user')) ||
      (msg.includes('teacher') && n.includes('teacher')) ||
      (msg.includes('attendance') && n.includes('attendance')) ||
      (msg.includes('fee') && n.includes('fee')) ||
      (msg.includes('class') && (n.includes('class') || n.includes('grade')));
  }).slice(0, Number(previous.config.maxCollectionsToSample || 6));
}
return [{ json: { ...previous, selectedCollections: selectedCollections.slice(0, Number(previous.config.maxCollectionsToSample || 6)), collectionSelectionReason: parsed.reason || null } }];

const { MongoClient, ObjectId } = require('mongodb');

function flattenFields(obj, prefix = '', depth = 0, maxDepth = 3, acc = new Set()) {
  if (!obj || typeof obj !== 'object' || depth > maxDepth) return acc;
  for (const [k, v] of Object.entries(obj)) {
    const fp = prefix ? `${prefix}.${k}` : k; acc.add(fp);
    if (v && typeof v === 'object' && !Array.isArray(v) && !(v instanceof ObjectId) && !(v instanceof Date)) flattenFields(v, fp, depth + 1, maxDepth, acc);
  }
  return acc;
}
function summarizeValue(v) {
  if (v instanceof ObjectId) return 'ObjectId';
  if (v instanceof Date) return 'Date';
  if (Array.isArray(v)) return `Array<${v.length ? summarizeValue(v[0]) : 'unknown'}>`;
  if (v === null) return 'null';
  if (typeof v === 'object') return 'Object';
  return typeof v;
}

const projectSchema = $json.projectSchema || {};
const staticCollections = projectSchema.collections || {};
const selectedCollections = Array.isArray($json.selectedCollections) ? $json.selectedCollections.slice(0, Number($json.config.maxCollectionsToSample || 6)) : [];

// Build a schema starting from the static knowledge for every selected collection.
const schema = {
  generatedAt: new Date().toISOString(),
  source: 'static_first_then_live_sample',
  databaseName: $json.config.databaseName,
  availableCollections: $json.collectionNames,
  selectedCollections,
  rules: projectSchema.rules || [],
  rolesGuide: projectSchema.rolesGuide || {},
  queryPatterns: projectSchema.queryPatterns || [],
  collections: {}
};

for (const name of selectedCollections) {
  const stat = staticCollections[name] || null;
  schema.collections[name] = {
    fromStatic: !!stat,
    purpose: stat?.purpose || null,
    model: stat?.model || null,
    fields: stat ? Object.keys(stat.fields || {}) : [],
    fieldTypes: stat?.fields || {},
    enums: stat?.enums || {},
    relations: stat?.relations || [],
    requiredOnCreate: stat?.requiredOnCreate || [],
    privacy: stat?.privacy || null,
    commonQueries: stat?.commonQueries || [],
    sampleShape: null,
    liveFieldsAdded: []
  };
}

if (!selectedCollections.length || $json.config.enableLiveSchemaSampling === false) {
  return [{ json: { ...$json, schema, schemaCreatedNow: false, schemaMode: 'static_only' } }];
}

const client = new MongoClient($json.config.mongoUri, { serverSelectionTimeoutMS: 8000, connectTimeoutMS: 8000, socketTimeoutMS: 15000, maxPoolSize: 2 });
try {
  await client.connect();
  const db = client.db($json.config.databaseName);
  const cache = db.collection($json.config.schemaCacheCollection || '_agent_schema_cache');
  const sampleLimit = Math.min(Number($json.config.schemaSampleLimit || 2), 3);

  for (const collectionName of selectedCollections) {
    const target = schema.collections[collectionName];
    let docs = [];
    try {
      docs = await db.collection(collectionName).find({}, { projection: { password: 0, data: 0 } }).limit(sampleLimit).toArray();
    } catch (e) {
      target.sampleWarning = `Could not sample collection: ${e.message}`;
      continue;
    }
    const liveFields = new Set();
    for (const doc of docs) {
      flattenFields(doc, '', 0, 3, liveFields);
      if (!target.sampleShape) {
        target.sampleShape = Object.fromEntries(Object.entries(doc).map(([k, v]) => [k, summarizeValue(v)]));
      }
    }
    const known = new Set(target.fields);
    for (const f of liveFields) {
      if (!known.has(f)) { target.fields.push(f); target.liveFieldsAdded.push(f); }
    }
    try {
      await cache.updateOne({ collectionName }, { $set: { collectionName, sample: target.sampleShape, updatedAt: new Date() }, $setOnInsert: { createdAt: new Date() } }, { upsert: true });
    } catch (e) { /* ignore cache write errors */ }
  }
  return [{ json: { ...$json, schema, schemaCreatedNow: false, schemaMode: 'static_plus_live_sample' } }];
} catch (e) {
  return [{ json: { ...$json, schema, schemaCreatedNow: false, schemaMode: 'static_only_db_error', schemaWarning: e.message } }];
} finally { await client.close(); }

const previous = $('Build AI Planning Prompt').first().json;

function parsePlan(content) {
  if (!content) throw new Error('OpenAI returned an empty plan');
  if (typeof content === 'object') return content;
  return JSON.parse(content);
}

const content = $json.choices?.[0]?.message?.content;
const plan = parsePlan(content);

const allowedOps = new Set(['find','aggregate','insertOne','updateOne','updateMany','deleteOne','deleteMany','explain','compose','writeBatch','bulkMarkAttendance']);

function isKnownCollection(name) {
  if (!name) return false;
  if (previous.schema && previous.schema.collections && previous.schema.collections[name]) return true;
  if (previous.projectSchema && previous.projectSchema.collections && previous.projectSchema.collections[name]) return true;
  if (Array.isArray(previous.collectionNames) && previous.collectionNames.indexOf(name) !== -1) return true;
  return false;
}

function getCollectionDef(name) {
  if (previous.schema && previous.schema.collections && previous.schema.collections[name]) return previous.schema.collections[name];
  if (previous.projectSchema && previous.projectSchema.collections && previous.projectSchema.collections[name]) return previous.projectSchema.collections[name];
  return null;
}
if (!allowedOps.has(plan.operation)) throw new Error(`Unsupported operation from AI plan: ${plan.operation}`);

const NO_MAIN_COLLECTION_OPS = new Set(['explain','compose','writeBatch']);
if (!NO_MAIN_COLLECTION_OPS.has(plan.operation)) {
  if (!plan.collection || !isKnownCollection(plan.collection)) {
    throw new Error(`AI selected unknown collection: ${plan.collection}`);
  }
}
if (plan.operation === 'compose') {
  plan.collection = null;
  if (!Array.isArray(plan.preResolve) || plan.preResolve.length === 0) {
    throw new Error('compose operation requires at least one preResolve step');
  }
}
if (plan.operation === 'writeBatch') {
  plan.collection = null;
  if (!Array.isArray(plan.writes) || plan.writes.length === 0) {
    throw new Error('writeBatch requires a non-empty "writes" array of write sub-plans');
  }
  if (plan.writes.length > 25) {
    throw new Error('writeBatch capped at 25 sub-writes');
  }
  const WRITE_OPS_SET = new Set(['insertOne','updateOne','updateMany','deleteOne','deleteMany']);
  for (let i = 0; i < plan.writes.length; i++) {
    const sub = plan.writes[i];
    if (!sub || typeof sub !== 'object') throw new Error(`writeBatch.writes[${i}] must be an object`);
    if (!WRITE_OPS_SET.has(sub.operation)) throw new Error(`writeBatch.writes[${i}].operation must be a WRITE op (insertOne/updateOne/updateMany/deleteOne/deleteMany), got: ${sub.operation}`);
    if (!sub.collection || !isKnownCollection(sub.collection)) throw new Error(`writeBatch.writes[${i}] unknown collection: ${sub.collection}`);
    if ((sub.operation === 'updateMany' || sub.operation === 'deleteMany') && (!sub.filter || Object.keys(sub.filter).length === 0)) {
      throw new Error(`writeBatch.writes[${i}] ${sub.operation} requires a non-empty filter`);
    }
    sub.preResolve = Array.isArray(sub.preResolve) ? sub.preResolve : [];
    sub.filter = sub.filter || {};
    sub.update = sub.update || {};
    sub.document = sub.document || {};
    sub.options = sub.options || {};
  }
  plan.requiresWrite = true;
}

plan.options = plan.options || {};
plan.options.limit = Math.min(Number(plan.options.limit || 20), Number(previous.config.maxResultLimit || 100));

// Validate preResolve steps
plan.preResolve = Array.isArray(plan.preResolve) ? plan.preResolve : [];
const seenAs = new Set();
for (const step of plan.preResolve) {
  if (!step || typeof step !== 'object') throw new Error('preResolve step must be an object');
  if (!step.as || typeof step.as !== 'string') throw new Error('preResolve step missing string "as"');
  if (seenAs.has(step.as)) throw new Error(`Duplicate preResolve.as: ${step.as}`);
  seenAs.add(step.as);
  if (!step.collection || !isKnownCollection(step.collection)) {
    throw new Error(`preResolve unknown collection: ${step.collection}`);
  }
  step.operation = step.operation || 'find';
  if (!['find','aggregate'].includes(step.operation)) {
    throw new Error(`preResolve operation must be find or aggregate, got ${step.operation}`);
  }
  step.filter = step.filter || {};
  step.pipeline = Array.isArray(step.pipeline) ? step.pipeline : [];
  step.projection = step.projection || (step.extractField ? { [step.extractField]: 1 } : {});
  step.extractField = step.extractField || null;
  step.extractAs = step.extractAs || 'array';
  if (!['array','first'].includes(step.extractAs)) step.extractAs = 'array';
  step.limit = Math.min(Number(step.limit || 50), 100);
  step.required = step.required !== false;
}

if ((plan.operation === 'updateMany' || plan.operation === 'deleteMany') &&
    (!plan.filter || Object.keys(plan.filter).length === 0)) {
  throw new Error(`${plan.operation} requires a non-empty filter`);
}

if (plan.operation === 'insertOne') {
  const def = getCollectionDef(plan.collection);
  const required = (def && def.requiredOnCreate) || [];
  const doc = plan.document || {};
  const missing = required.filter(f => doc[f] === undefined || doc[f] === null || doc[f] === '');
  if (missing.length) {
    plan.operation = 'explain';
    plan.missingFields = missing;
    plan.message = `I can create the ${plan.collection} record once you provide: ${missing.join(', ')}.`;
    plan.requiresWrite = false;
  }
}

function applyPrivacyProjection(projection, excludeFields) {
  const proj = { ...(projection || {}) };
  const inclusionKeys = Object.keys(proj).filter(k => k !== '_id' && (proj[k] === 1 || proj[k] === true));
  if (inclusionKeys.length > 0) {
    // Inclusion mode: just make sure the sensitive fields are NOT listed.
    // We cannot also add `password:0` because Mongo forbids mixing inclusion and exclusion in one find projection.
    for (const f of excludeFields) {
      if (proj[f] === 1 || proj[f] === true) delete proj[f];
    }
    const stillIncluding = Object.keys(proj).some(k => k !== '_id' && (proj[k] === 1 || proj[k] === true));
    if (!stillIncluding) {
      // The only inclusion was the field we just removed; fall back to exclusion-only mode.
      for (const f of excludeFields) proj[f] = 0;
    }
  } else {
    // Empty {} or pure-exclusion projection: add explicit exclusion.
    for (const f of excludeFields) proj[f] = 0;
  }
  return proj;
}

if (plan.operation === 'find') {
  if (plan.collection === 'users') plan.projection = applyPrivacyProjection(plan.projection, ['password']);
  if (plan.collection === 'chatfiles' || plan.collection === 'homeworkfiles') {
    plan.projection = applyPrivacyProjection(plan.projection, ['data']);
  }
}
if (plan.operation === 'aggregate' && Array.isArray(plan.pipeline)) {
  if (plan.collection === 'users') plan.pipeline.unshift({ $project: { password: 0 } });
  if (plan.collection === 'chatfiles' || plan.collection === 'homeworkfiles') {
    plan.pipeline.unshift({ $project: { data: 0 } });
  }
}

if (['insertOne','updateOne','updateMany','deleteOne','deleteMany'].includes(plan.operation)) {
  plan.requiresWrite = true;
}
if (plan.operation === 'bulkMarkAttendance') {
  plan.collection = plan.collection || 'attendances';
  if (!Array.isArray(plan.sections)) plan.sections = [];
  if (plan.sections.length > 50) throw new Error('bulkMarkAttendance capped at 50 sections per turn');
  // sections.length === 0 means "expand to every active class+section at execute time".
  for (let i = 0; i < plan.sections.length; i++) {
    const s = plan.sections[i];
    if (!s || typeof s !== 'object' || !s.class) throw new Error(`bulkMarkAttendance.sections[${i}] missing class`);
  }
  if (!plan.status || !['present','absent','late','excused'].includes(plan.status)) {
    throw new Error(`bulkMarkAttendance.status must be one of present|absent|late|excused, got: ${plan.status}`);
  }
  if (!plan.date) throw new Error('bulkMarkAttendance.date is required');
  plan.requiresWrite = true;
}

return [{ json: { ...previous, plan } }];

/**
 * Inline RBAC ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â aligned with backend/src/routes/*.js (read from codebase).
 * Roles: Admin, Principal, Finance (alias Accountant), HR, Receptionist (alias Reception),
 *        Teacher, Student, Parent.
 * Admin has full access. Bulk writes (updateMany/deleteMany) blocked for non-Admin.
 */

async function checkRBAC(ctx) {
  const POLICY_VERSION = '2026-06-15-v3-codebase-aligned';

  function normalizeRole(role) {
    if (!role) return '';
    const raw = String(role).trim();
    const lower = raw.toLowerCase();
    if (lower === 'principle')  return 'Principal';
    if (lower === 'reception' || lower === 'receptionist') return 'Receptionist';
    if (lower === 'accountant' || lower === 'finance')     return 'Finance';
    const canon = ['Admin','Principal','Finance','HR','Receptionist','Teacher','Student','Parent'];
    return canon.find(r => r.toLowerCase() === lower) || raw;
  }

  // Collection -> coarse module key for the policy lookup
  const COLLECTION_TO_MODULE = {
    attendances: 'attendance', attendanceassignments: 'attendance',
    staffattendances: 'staffAttendance',
    users: 'users',
    students: 'students', studentcertificates: 'students',
    teachers: 'teachers',
    parents: 'parents',
    schoolclasses: 'classes', levelsettings: 'classes', roomsettings: 'classes',
    subjects: 'subjects',
    syllabuses: 'syllabus',
    exams: 'exams', examconfigs: 'exams', exammarks: 'exams',
    marksheets: 'marksheets',
    reportcards: 'reportCards', gradescales: 'reportCards',
    homeworks: 'homeworks', homeworkfiles: 'homeworks', homeworknotifications: 'homeworks',
    dailydiaries: 'dailyDiary',
    fees: 'fees', feevouchertemplates: 'fees',
    financesettings: 'finance', financecategories: 'finance',
    financeexpenses: 'finance', financeincomes: 'finance',
    financeliabilities: 'finance', financeliabilityrepayments: 'finance',
    salarystaffs: 'salary', salarystructures: 'salary', salaryslips: 'salary',
    transports: 'transport', transportroutes: 'transport',
    transportenrollments: 'transport', transportpayments: 'transport', transportrequests: 'transport',
    timetables: 'timetables',
    complaints: 'complaints', complaintcategories: 'complaints',
    notifications: 'notifications', notificationreads: 'notifications', fcmtokens: 'notifications',
    messages: 'messages', messagedeliveries: 'messages',
    chatsessions: 'chat', chatmessages: 'chat', chatfiles: 'chat',
    librarybooks: 'library', libraryissues: 'library',
    inventoryitems: 'inventory', inventorycategories: 'inventory',
    inventorystockmovements: 'inventory', inventorydistributions: 'inventory',
    hostels: 'hostel', hostelrooms: 'hostel', hostelresidents: 'hostel', hostelfees: 'hostel',
    departments: 'departments',
    refreshtokens: 'auth', passwordresets: 'auth'
  };

  const OP_TO_METHOD = {
    find: 'GET', aggregate: 'GET', explain: 'GET',
    insertOne: 'POST',
    updateOne: 'PATCH', updateMany: 'PATCH',
    deleteOne: 'DELETE', deleteMany: 'DELETE',
    bulkMarkAttendance: 'PATCH'
  };

  // Per-module, per-role allowed methods. Compiled from every route file.
  // Admin is special-cased (full access) below ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â not listed here.
  const POLICY = {
    // FR-1 student attendance
    attendance: {
      Principal:    ['GET','PATCH','DELETE'],
      HR:           ['GET'],
      Finance:      [],
      Receptionist: ['GET'],
      Teacher:      ['GET','POST','PATCH'],     // teacher marks + edits own classes
      Student:      ['GET'],
      Parent:       ['GET']
    },
    staffAttendance: {
      Principal:    ['GET','POST','PATCH'],
      HR:           ['GET','DELETE'],
      Finance:      [],
      Receptionist: ['GET','POST'],
      Teacher:      ['GET'],
      Student:      [],
      Parent:       []
    },
    users: {
      Principal:    ['GET','POST','PATCH'],   // Principal can create + edit HR / Finance / Reception staff
      HR:           [],
      Finance:      [],
      Receptionist: [],
      Teacher:      [],
      Student:      [],
      Parent:       []
    },
    students: {
      Principal:    ['GET','POST','PATCH'],     // admission too
      HR:           ['GET','POST'],             // admission only
      Finance:      [],
      Receptionist: ['GET','POST','PATCH','DELETE'],
      Teacher:      ['GET'],
      Student:      ['GET'],
      Parent:       ['GET']
    },
    teachers: {
      Principal:    ['GET','POST','PATCH','DELETE'],
      HR:           ['GET','POST','PATCH'],
      Finance:      [],
      Receptionist: ['GET'],
      Teacher:      ['GET'],
