const { MongoClient, ObjectId } = require('mongodb');

const ARRAY_OPERATORS = new Set(['$in', '$nin', '$all']);
const SCALAR_OPERATORS = new Set(['$eq', '$ne', '$gt', '$gte', '$lt', '$lte']);
const REGEX_LIKE_KEYS = new Set(['$regex', '$options']);

function isRefMarker(value) {
  return value && typeof value === 'object' && !Array.isArray(value)
    && Object.keys(value).length === 1 && typeof value.$ref === 'string';
}

function substituteRefs(value, resolved) {
  if (Array.isArray(value)) return value.map(v => substituteRefs(v, resolved));
  if (value && typeof value === 'object' && !(value instanceof Date)) {
    if (value._bsontype === 'ObjectID' || value._bsontype === 'ObjectId') return value;
    if (isRefMarker(value)) {
      const key = value.$ref;
      // Support flat key or dot-path: "studentId" or "studentDoc._id" or "userDoc.0.name"
      if (key in resolved) return resolved[key];
      const parts = String(key).split('.');
      if (parts.length > 1 && parts[0] in resolved) {
        let cur = resolved[parts[0]];
        for (let i = 1; i < parts.length; i++) {
          if (cur === null || cur === undefined) break;
          if (Array.isArray(cur)) {
            // map over array if path continues into element field
            cur = cur.map(item => (item == null ? null : item[parts[i]])).filter(v => v !== undefined);
          } else {
            cur = cur[parts[i]];
          }
        }
        if (cur === undefined || cur === null) {
          throw new Error(`Unresolved $ref dot-path: "${key}" - segment yielded null/undefined.`);
        }
        return cur;
      }
      throw new Error(`Unresolved $ref placeholder: "${key}". Define a preResolve step with as="${parts[0]}".`);
    }
    const out = {};
    for (const [k, v] of Object.entries(value)) out[k] = substituteRefs(v, resolved);
    return out;
  }
  return value;
}

function sanitizeFilter(value, warnings, path) {
  if (path === undefined) path = '';
  if (Array.isArray(value)) return value.map((v, i) => sanitizeFilter(v, warnings, `${path}[${i}]`));
  if (!value || typeof value !== 'object' || value instanceof Date) return value;
  if (value._bsontype === 'ObjectID' || value._bsontype === 'ObjectId') return value;

  const out = {};
  for (const [k, v] of Object.entries(value)) {
    if (ARRAY_OPERATORS.has(k)) {
      if (isRefMarker(v)) { out[k] = v; continue; }
      if (v && typeof v === 'object' && !Array.isArray(v)) {
        const innerKeys = Object.keys(v);
        if (innerKeys.length && innerKeys.every(ik => REGEX_LIKE_KEYS.has(ik))) {
          warnings.push(`Auto-fixed: ${k} wrapping around $regex at ${path}; lifted to parent.`);
          out.__liftToParent__ = v;
          continue;
        }
        if (innerKeys.length === 1 && innerKeys[0] === '$eq') {
          warnings.push(`Auto-fixed: ${k} contained $eq at ${path}; converted to array.`);
          out[k] = [v.$eq];
          continue;
        }
        warnings.push(`Suspicious: ${k} value is an object with keys [${innerKeys.join(',')}] at ${path}. Wrapping in array as best-effort.`);
        out[k] = [v];
        continue;
      }
      if (!Array.isArray(v)) {
        warnings.push(`Auto-fixed: ${k} value was a scalar at ${path}; wrapped in array.`);
        out[k] = [v];
        continue;
      }
      out[k] = v.map((item, i) => {
        if (item && typeof item === 'object' && !Array.isArray(item) && !(item instanceof Date)) {
          return sanitizeFilter(item, warnings, `${path}.${k}[${i}]`);
        }
        return item;
      });
      continue;
    }
    if (SCALAR_OPERATORS.has(k)) {
      if (v && typeof v === 'object' && !Array.isArray(v) && !(v instanceof Date) && !isRefMarker(v)) {
        const innerKeys = Object.keys(v);
        if (innerKeys.length === 1 && SCALAR_OPERATORS.has(innerKeys[0])) {
          warnings.push(`Auto-fixed: stripped nested ${innerKeys[0]} inside ${k} at ${path}.`);
          out[k] = v[innerKeys[0]];
          continue;
        }
        if (k === '$eq' && innerKeys.length && innerKeys.every(ik => REGEX_LIKE_KEYS.has(ik))) {
          warnings.push(`Auto-fixed: $eq wrapping $regex at ${path}; lifted to parent.`);
          out.__liftToParent__ = v;
          continue;
        }
      }
      out[k] = v;
      continue;
    }
    out[k] = sanitizeFilter(v, warnings, `${path}.${k}`);
  }

  for (const [fieldName, fieldVal] of Object.entries(out)) {
    if (fieldVal && typeof fieldVal === 'object' && '__liftToParent__' in fieldVal) {
      const lifted = fieldVal.__liftToParent__;
      const rest = { ...fieldVal };
      delete rest.__liftToParent__;
      out[fieldName] = { ...rest, ...lifted };
    }
  }
  return out;
}

function nowDate() { return new Date(); }
function withInsertTimestamps(doc) {
  if (!doc || typeof doc !== 'object' || Array.isArray(doc) || doc instanceof Date) return doc;
  const out = Object.assign({}, doc);
  const now = nowDate();
  if (!out.createdAt) out.createdAt = now;
  if (!out.updatedAt) out.updatedAt = now;
  return out;
}
function withUpdateTimestamps(update) {
  if (!update || typeof update !== 'object') return update;
  const setKey = String.fromCharCode(36) + 'set';
  const soiKey = String.fromCharCode(36) + 'setOnInsert';
  const hasOps = Object.keys(update).some(function(k){ return k.charCodeAt(0) === 36; });
  const out = Object.assign({}, update);
  const now = nowDate();
  if (hasOps) {
    out[setKey] = Object.assign({}, out[setKey] || {}, { updatedAt: now });
    if (out[soiKey]) {
      out[soiKey] = Object.assign({}, out[soiKey]);
      if (!out[soiKey].createdAt) out[soiKey].createdAt = now;
    } else {
      out[soiKey] = { createdAt: now };
    }
  } else {
    out.updatedAt = now;
    if (!out.createdAt) out.createdAt = now;
  }
  return out;
}

function convertObjectIds(value) {
  if (Array.isArray(value)) return value.map(convertObjectIds);
  if (value && typeof value === 'object') {
    if (value instanceof Date) return value;
    if (value._bsontype === 'ObjectID' || value._bsontype === 'ObjectId') return value;
    // Unwrap BSON extended-JSON single-key markers BEFORE recursing so {$date: "iso"} becomes Date, not {$date: Date}.
    const keys = Object.keys(value);
    if (keys.length === 1) {
      const k = keys[0];
      const v = value[k];
      if (k === '$date' && typeof v === 'string') return new Date(v);
      if (k === '$date' && v && typeof v === 'object' && typeof v.$numberLong === 'string') return new Date(Number(v.$numberLong));
      if (k === '$oid'  && typeof v === 'string' && /^[a-fA-F0-9]{24}$/.test(v)) return new ObjectId(v);
    }
    const out = {};
    for (const [key, val] of Object.entries(value)) {
      if (typeof val === 'string' && /^[a-fA-F0-9]{24}$/.test(val)) out[key] = new ObjectId(val);
      else out[key] = convertObjectIds(val);
    }
    return out;
  }
  return value;
}

function sanitizePipeline(pipeline) {
  if (!Array.isArray(pipeline)) return [];
  const blocked = new Set(['$out', '$merge', '$function', '$accumulator']);
  for (const stage of pipeline) {
    const stageName = Object.keys(stage || {})[0];
    if (blocked.has(stageName)) throw new Error(`Blocked unsafe aggregate stage: ${stageName}`);
  }
  return pipeline;
}

async function runPreResolve(db, steps, maxResultLimit) {
  const resolved = {};
  const trace = [];
  for (const step of steps || []) {
    const coll = db.collection(step.collection);
    const limit = Math.min(Number(step.limit || 50), Number(maxResultLimit || 100));
    let docs;
    if (step.operation === 'aggregate') {
      // Substitute $ref placeholders with values resolved by earlier preResolve steps.
      const substitutedPipeline = substituteRefs(step.pipeline || [], resolved);
      const pipeline = convertObjectIds(sanitizePipeline(substitutedPipeline));
      if (!pipeline.some(s => s.$limit)) pipeline.push({ $limit: limit });
      docs = await coll.aggregate(pipeline).toArray();
    } else {
      const substitutedFilter = substituteRefs(step.filter || {}, resolved);
      const filter = convertObjectIds(sanitizeFilter(substitutedFilter, [], `preResolve[${step.as}].filter`));
      let cursor = coll.find(filter);
      if (step.projection && Object.keys(step.projection).length) cursor = cursor.project(step.projection);
      docs = await cursor.limit(limit).toArray();
    }
    let value;
    if (step.extractField) {
      value = docs.map(d => d && d[step.extractField]).filter(v => v !== undefined && v !== null);
    } else {
      value = docs;
    }
    if (step.extractAs === 'first') value = value.length ? value[0] : null;

    const isEmpty = (value === null) || (Array.isArray(value) && value.length === 0);
    if (isEmpty && step.required) {
      const err = new Error(`preResolve "${step.as}" returned no results.`);
      err.userFacing = step.ifEmptyMessage || `No matching ${step.collection} record was found for "${step.as}".`;
      err.preResolveStep = step.as;
      throw err;
    }
    resolved[step.as] = value;
    trace.push({ as: step.as, collection: step.collection, count: Array.isArray(value) ? value.length : (value ? 1 : 0) });
  }
  return { resolved, trace };
}

async function executeMongoPlan(db, plan, maxResultLimit) {
  if (plan.operation === 'explain') {
    return { type: 'message', data: null, message: plan.message || plan.reason || 'The request needs clarification.', preResolveTrace: [] };
  }

  if (plan.operation === 'compose') {
    const composed = await runPreResolve(db, plan.preResolve || [], maxResultLimit);
    return {
      type: 'compose',
      data: composed.resolved,
      preResolveTrace: composed.trace,
      filterWarnings: []
    };
  }

  if (plan.operation === 'bulkMarkAttendance') {
    const studentsColl = db.collection('students');
    const attColl = db.collection('attendances');
    const dateVal = (function(){
      if (plan.date && typeof plan.date === 'object' && typeof plan.date.$date === 'string') return new Date(plan.date.$date);
      if (typeof plan.date === 'string') return new Date(plan.date);
      return plan.date instanceof Date ? plan.date : new Date();
    })();
    dateVal.setHours(0,0,0,0);
    const callerUserId = (function(){
      const u = plan.callerUserId || plan.teacher;
      if (typeof u === 'string' && /^[a-fA-F0-9]{24}$/.test(u)) return new ObjectId(u);
      return null;
    })();
    let sectionsToProcess = plan.sections;
    if (!sectionsToProcess || sectionsToProcess.length === 0) {
      // School-wide: expand to every (class, section) in active schoolclasses.
      const classDocs = await db.collection('schoolclasses').find({ active: true }).project({ name:1, sections:1 }).toArray();
      sectionsToProcess = [];
      for (const c of classDocs) {
        const secs = Array.isArray(c.sections) && c.sections.length ? c.sections : [null];
        for (const sec of secs) sectionsToProcess.push({ class: c.name, section: sec || null });
      }
      if (sectionsToProcess.length === 0) {
        return { type:'bulkMarkAttendance', data:{ status:plan.status, date:dateVal.toISOString().slice(0,10), perSection:[] }, preResolveTrace:[], filterWarnings:[], message:'No active classes found to mark.' };
      }
    }
    const perSection = [];
    for (const s of sectionsToProcess) {
      const cls = String(s.class).trim();
      const sec = s.section ? String(s.section).trim() : null;
      const filter = sec ? { class: cls, section: sec, status: 'incampus' } : { class: cls, status: 'incampus' };
      const studs = await studentsColl.find(filter, { projection: { _id: 1, class: 1, section: 1 } }).toArray();
      if (studs.length === 0) { perSection.push({ class: cls, section: sec, ok: false, error: `No students found in class ${cls}${sec? ' section '+sec:''}.`, modifiedCount: 0, upsertedCount: 0 }); continue; }
      const _now = nowDate();
      const ops = studs.map(st => ({
        updateOne: {
          filter: { student: st._id, date: dateVal },
          update: { $set: { status: plan.status, teacher: callerUserId || undefined, class: st.class, section: st.section, updatedAt: _now }, $setOnInsert: { createdAt: _now, remarks: '' } },
          upsert: true
        }
      }));
      const bw = await attColl.bulkWrite(ops, { ordered: false });
      perSection.push({
        class: cls, section: sec, ok: true,
        totalStudents: studs.length,
        matchedCount: bw.matchedCount,
        modifiedCount: bw.modifiedCount,
        upsertedCount: bw.upsertedCount || (bw.upsertedIds ? Object.keys(bw.upsertedIds).length : 0)
      });
    }
    return {
      type: 'bulkMarkAttendance',
      data: { status: plan.status, date: dateVal.toISOString().slice(0,10), perSection },
      preResolveTrace: [],
      filterWarnings: []
    };
  }

  if (plan.operation === 'writeBatch') {
    const subResults = [];
    const aggregatedTrace = [];
    let totalMatched = 0, totalModified = 0, totalUpserted = 0, totalDeleted = 0, totalInserted = 0;
    for (let i = 0; i < (plan.writes || []).length; i++) {
      const sub = plan.writes[i];
      try {
        const r = await executeMongoPlan(db, sub, maxResultLimit);
