  }
  if (execution?.type === 'message') return execution.message || 'Done.';
  const raw = execution?.data;
  if (Array.isArray(raw)) {
    const lower = String(message || '').toLowerCase();
    if (lower.includes('how many') || lower.includes('count')) return String(raw.length);
    if (lower.includes('list') || lower.includes('names')) return recordsToBulletList(raw);
    return recordsToMarkdownTable(raw);
  }
  if (raw && typeof raw === 'object') {
    const parts = [];
    if ('insertedId' in raw) parts.push(`Inserted ID: ${raw.insertedId}`);
    if ('matchedCount' in raw) parts.push(`Matched: ${raw.matchedCount}`);
    if ('modifiedCount' in raw) parts.push(`Modified: ${raw.modifiedCount}`);
    if ('deletedCount' in raw) parts.push(`Deleted: ${raw.deletedCount}`);
    if (parts.length) return parts.join('\n');
  }
  return plan?.reason || 'Done.';
}

const formatted = safeJsonParse($json.choices?.[0]?.message?.content, {});
const exportFile = previous.exportFile || null;
let finalAnswer = formatted.answer || previous.execution?.message || buildFallbackAnswer(previous.message, previous.execution, previous.plan, exportFile);
// If the formatter inserted any [Download ...](...) link of its own (likely with a broken placeholder href), strip them.
if (exportFile && exportFile.dataUrl && typeof finalAnswer === 'string') {
  const stripLink = new RegExp('\\[Download[^\\]]*\\]\\([^)]*\\)', 'g');
  const collapseBlank = new RegExp('\\n{3,}', 'g');
  finalAnswer = finalAnswer.replace(stripLink, '').replace(collapseBlank, String.fromCharCode(10) + String.fromCharCode(10)).trim();
}
// Hard guarantee: if an export file was generated, the answer MUST contain its download link.
if (exportFile && exportFile.dataUrl && typeof finalAnswer === 'string' && finalAnswer.indexOf(exportFile.dataUrl) === -1) {
  const note = exportFile.fallback ? (' _(' + exportFile.fallback.replace(/_/g, ' ') + (exportFile.fallbackDetail ? ' - ' + exportFile.fallbackDetail : '') + ')_') : '';
  const link = '[Download ' + exportFile.filename + '](' + exportFile.dataUrl + ')' + note;
  const sep = String.fromCharCode(10) + String.fromCharCode(10);
  finalAnswer = (finalAnswer && finalAnswer.trim()) ? (finalAnswer.trim() + sep + link) : link;
}

const rawResult = previous.execution?.data ?? null;
const resultCount = Array.isArray(rawResult) ? rawResult.length : null;

return [{
  json: {
    ok: true,
    statusCode: 200,
    requestId: previous.requestId,
    sessionId: previous.sessionId,
    userId: previous.userId,
    email: previous.email,
    role: previous.role,
    answer: finalAnswer,
    data: {
      metadataOnly: true,
      resultCount,
      operation: previous.plan?.operation,
      collection: previous.plan?.collection,
      schemaMode: previous.schemaMode,
      rbacAllowed: true,
      exportFile: exportFile ? { format: exportFile.format, filename: exportFile.filename, mimeType: exportFile.mimeType, dataLength: exportFile.dataLength, fallback: exportFile.fallback || null } : null
    },
    operationSummary: formatted.operationSummary || previous.plan?.reason || previous.plan?.operation,
    operation: previous.plan?.operation,
    collection: previous.plan?.collection,
    schemaCreatedNow: previous.schemaCreatedNow,
    schemaMode: previous.schemaMode,
    intent: previous.intent,
    rbac: { allowed: true },
    exportType: exportFile?.format || null
  }
}];

function scrubAnswerForMemory(s) {
  if (typeof s !== 'string' || s.length === 0) return s;
  // Replace base64 data URLs (PDF/Word/Excel exports) with a short placeholder so memory doesn't grow without bound.
  return s.replace(/data:[^;,]+;base64,[A-Za-z0-9+/=]{40,}/g, '[exported-binary]');
}
const { MongoClient } = require('mongodb');
const previous = $('Build AI Response Formatter Prompt').first().json;

function extractEntities(data, collection) {
  if (!Array.isArray(data)) return [];
  return data.slice(0, 5).map(row => {
    if (!row || typeof row !== 'object') return null;
    const out = { collection };
    if (row._id !== undefined && row._id !== null) out._id = String(row._id);
    for (const key of ['name','title','email','studentId','registrationNumber','employeeId','rollNumber','phone','username','className','class','section','teacherName','designation']) {
      if (typeof row[key] === 'string') out[key] = row[key];
    }
    if (row.userDoc && typeof row.userDoc === 'object' && row.userDoc.name) out.linkedName = String(row.userDoc.name);
    if (row.studentUser && typeof row.studentUser === 'object' && row.studentUser.name) out.linkedName = String(row.studentUser.name);
    if (row.user && typeof row.user === 'object' && row.user.name) out.linkedName = String(row.user.name);
    return Object.keys(out).length > 1 ? out : null;
  }).filter(Boolean);
}

function shallow(value, maxKeys) {
  if (value === null || value === undefined) return null;
  if (typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.slice(0, maxKeys || 20);
  const out = {};
  const keys = Object.keys(value).slice(0, maxKeys || 20);
  for (const k of keys) {
    const v = value[k];
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      // keep $ref markers literal; truncate other objects to a single level
      if (Object.keys(v).length === 1 && typeof v.$ref === 'string') out[k] = v;
      else out[k] = { ...v };
    } else {
      out[k] = v;
    }
  }
  return out;
}

function compactPlan(plan) {
  if (!plan || typeof plan !== 'object') return null;
  return {
    operation: plan.operation,
    collection: plan.collection,
    document: shallow(plan.document, 30),
    update: shallow(plan.update, 30),
    filter: shallow(plan.filter, 30),
    preResolveSummary: Array.isArray(plan.preResolve) ? plan.preResolve.map(s => ({
      as: s.as,
      collection: s.collection,
      operation: s.operation || 'find',
      filter: shallow(s.filter, 10),
      extractField: s.extractField || null,
      extractAs: s.extractAs || 'array'
    })) : []
  };
}

function extractProvidedFields(plan) {
  if (!plan) return null;
  if (plan.operation === 'insertOne') {
    return plan.document && typeof plan.document === 'object' ? Object.keys(plan.document) : [];
  }
  if (plan.operation === 'updateOne' || plan.operation === 'updateMany') {
    if (plan.update && plan.update.$set && typeof plan.update.$set === 'object') return Object.keys(plan.update.$set);
    return plan.update && typeof plan.update === 'object' ? Object.keys(plan.update) : [];
  }
  return null;
}

const lastEntities = extractEntities(previous.execution?.data, previous.plan?.collection);
const planCompact = compactPlan(previous.plan);
const providedFields = extractProvidedFields(previous.plan);
const exec = previous.execution || {};
const success = ['data','writeResult','compose','writeBatch','bulkMarkAttendance'].includes(exec.type);
let failureReason = null;
if (!success) {
  if (exec.preResolveError) failureReason = `preResolve "${exec.preResolveStep || ''}" empty: ${exec.preResolveError}`;
  else if (exec.type === 'message') failureReason = exec.message || null;
}

const client = new MongoClient(previous.config.mongoUri, { serverSelectionTimeoutMS: 8000, connectTimeoutMS: 8000, socketTimeoutMS: 12000, maxPoolSize: 2 });
try {
  await client.connect();
  const db = client.db(previous.config.databaseName);
  await db.collection(previous.config.memoryCollection || '_agent_chat_memory').insertOne({
    sessionId: previous.sessionId,
    userId: previous.userId,
    email: previous.email,
    role: previous.role,
    userMessage: previous.message,
    assistantAnswer: scrubAnswerForMemory($json.answer),
    intent: previous.intent,
    operation: $json.operation,
    collection: $json.collection,
    plan: planCompact,
    providedFields,
    success,
    failureReason,
    resultCount: $json.data?.resultCount ?? null,
    lastEntities,
    exportType: $json.exportType || null,
    createdAt: new Date()
  });
  return [{ json: $json }];
} catch (e) {
  return [{ json: { ...$json, memorySaveWarning: e.message } }];
} finally { await client.close(); }
